insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4af1893d-9998-48eb-b854-d76a961d685a', 'de', 'Warum solltest du Nähe nach und nach verändern statt abrupt?', '["Abrupte Bewegungen wirken aufdringlich und zerstören die Verbindung", "Allmähliche Veränderungen passen zur wachsenden Stimmung", "Schnelle Nähe zeigt immer starkes Interesse"]'::jsonb, 'Langsames Vorgehen erhält Sicherheit und Feingefühl.')
