insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'de', 'Was erzeugt den „Funken“ knisternder Spannung?', '["Eine leise Ungewissheit, ob es mehr als platonisch ist", "Alles vorhersehbar und freundschaftlich halten", "Früh ausdrücklich romantische Absichten erklären", "Jede körperliche Wahrnehmung vermeiden"]'::jsonb, 'Die Frage „Ist das hier mehr?“ hält die Aufmerksamkeit wach.')
