insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9af130c-ceeb-430c-817a-3b39ec63ff4b', 'de', 'Was beschreibt eine kleine Herausforderung beim Flirten am besten?', '["Ein verspieltes Hin und Her, das sie einbezieht, ohne dass etwas davon abhängt", "Ein Test, wie klug oder geschickt sie ist", "Eine Art Necken, die sie in Verlegenheit bringen soll"]'::jsonb, 'Eine kleine Herausforderung ist gemeinsames, harmloses Spiel. Es steht nichts Echtes auf dem Spiel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ac1764e4-0635-4b2a-a9b1-3d396b43c335', 'de', 'Welche Signale zeigen, dass du etwas näher kommen kannst?', '["Sie bleibt entspannt, wenn du näher kommst", "Sie lehnt sich beim Reden vor", "Sie hält Blickkontakt", "Sie schaut sich oft im Raum um"]'::jsonb, 'Wohlgefühl zeigt sich durch Ruhe, Erwidern und entspannte Beteiligung.')
