insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af902d35-dd20-4ecf-9ebd-6cc05bed06fb', 'de', 'Warum musst du die reine Vertrautheit durchbrechen, damit es knistert?', '["Reine Vertrautheit hält Begegnungen platonisch und vorhersehbar", "Der Bruch wirft die Frage auf, ob mehr daraus werden könnte", "Ständige Vertrautheit baut immer Anziehung auf"]'::jsonb, 'Spannung entsteht, wenn du mehr als Freundschaft andeutest.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b39a64ab-2d91-47b4-9ea1-8646ba10c538', 'de', 'Warum bleibt die Anziehung oft stecken, wenn du jede Berührung vermeidest?', '["Es fühlt sich langweilig an", "Die Begegnung wirkt platonisch", "Es zeigt mangelndes Selbstbewusstsein", "Es bremst das Gespräch"]'::jsonb, 'Ohne körperlichen nächsten Schritt kann die Begegnung freundschaftlich statt flirtend bleiben.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4ae1063-f21b-4c92-b4e9-ddeb53c5685f', 'de', 'Sie lehnt sich beim Reden an die Bar. Wie kannst du das spiegeln?', '["Steif bleiben, um Selbstbewusstsein zu zeigen", "Sofort genau ihre Haltung kopieren", "Näher kommen, um weiterzugehen", "Nach und nach eine ähnlich entspannte Haltung einnehmen"]'::jsonb, 'Dezentes Angleichen schafft Wohlgefühl, ohne gespielt zu wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4cb96a5-9dac-4da8-9559-0e356ea4eeeb', 'de', 'Warum baut fein abgestimmte Berührung so wirksam Anziehung auf?', '["Sie zeigt romantisches Interesse ohne Worte", "Sie fügt einer bestehenden Verbindung eine körperliche Ebene hinzu", "Sie wirkt am besten, wenn sie forsch und häufig ist"]'::jsonb, 'Bewusste Berührung stärkt die Chemie, wenn sie zu ihrem Wohlgefühl passt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5aafcca-ae9a-48c1-974b-435701916b85', 'de', 'Sie sagt, dass sie richtig gut mit Karten umgehen kann. Was ist eine flirtende Antwort?', '["„Kannst du mir dann den Weg zu deinem Herzen zeigen?“", "„Du solltest wohl öfter ein Navi benutzen.“", "„Das ist ganz schön arrogant, haha.“", "„Den Weg finden ist doch nicht so schwer.“"]'::jsonb, 'Flirtender Humor baut Anziehung auf, indem er verspielt an ihre Aussage anknüpft.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b60b077a-0761-4330-9234-8fdcc1b81325', 'de', 'Warum baut das Spiegeln der Körpersprache unbewusst eine Verbindung auf?', '["Das Gehirn nimmt angeglichene Körpersprache als sicher, vertraut und vertrauenswürdig wahr", "Es zeigt, dass du aufmerksam und bei ihr bist", "Es zeigt soziale Intelligenz und emotionale Aufmerksamkeit"]'::jsonb, 'Spiegeln signalisiert unbewusst Vertrautheit und Leichtigkeit, und das stärkt die Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b70c5e9d-c782-4a54-be4f-ed860758730b', 'de', 'Welche Art von Komplimenten ist am besten?', '["Zu ihrem Stil, Humor oder ihrer Sichtweise", "Zu ihrer Mühe oder wie sie an Dinge herangeht", "Zu etwas, das sie gewählt oder gezeigt hat, nicht in die Wiege gelegt bekommen", "Alle oben genannten"]'::jsonb, 'Komplimente kommen am besten an, wenn sie etwas würdigen, das sie selbst gewählt hat, nicht ihre Merkmale.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc66a400-41a9-4f56-9e78-344908ee749c', 'de', 'Warum kann Berührung Anziehung stärker beschleunigen als Worte allein?', '["Sie schafft körperliche Bindung und Wohlgefühl", "Sie umgeht das rationale Denken", "Sie zeigt Dominanz", "Sie beweist Selbstbewusstsein"]'::jsonb, 'Berührung weckt Vertrauen und Bindung, wie es Worte allein nicht können.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bd77420f-f0c3-434d-a194-ed4c67dc0f59', 'de', 'Nach einer leichten Berührung am Arm weicht sie etwas zurück. Was solltest du tun?', '["Ihr Raum lassen und ohne weitere Berührung weitermachen", "Sie noch mal berühren, um Selbstbewusstsein zu zeigen", "Dich entschuldigen und nächstes Mal um Erlaubnis fragen", "Zu einer anderen Berührung übergehen"]'::jsonb, 'Respektier ihre Reaktion und lass das Körperliche erst mal ruhen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c23fa6ee-381a-4d27-bf59-41f86d51451f', 'de', 'Sie zieht dich leicht auf und lacht. Was könntest du sagen, um den Moment kippen zu lassen?', '["„Deine Augen leuchten richtig, wenn du lachst. Gefällt mir.“", "„Du bist witzig.“", "„Guter Witz.“", "„Die Runde geht an dich.“"]'::jsonb, 'Ein sanfter Ton und eine konkrete Beobachtung deuten Anziehung an, ohne schwer zu wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c595ee3e-bb2d-4d31-8268-40919fdef131', 'de', 'Sie prahlt verspielt damit, wie ehrgeizig sie beim Tennis ist. Was könntest du sagen?', '["„Das ist nicht immer gut.“", "„Ich liebe Herausforderungen. Aber nicht weinen, wenn ich gewinne.“", "„Wettbewerb ist ungesund.“", "„Erzähl mir mehr darüber.“"]'::jsonb, 'Greif ihre Verspieltheit auf, um Schlagabtausch und Energie zu steigern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c98b4016-8474-4fa7-b00d-224a8135153a', 'de', 'Welcher Gedanke hilft dir vor dem Ansprechen am besten in die richtige innere Haltung?', '["„Ich muss auffallen.“", "„Vielleicht hab ich heute Abend Glück.“", "„Ich muss selbstbewusst sein.“", "„Mein Ziel ist, einen schönen Moment zu schaffen.“"]'::jsonb, 'Diese Haltung hält dich geerdet, präsent und frei von Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbbc6dae-7dab-4dde-93eb-57bc3de19179', 'de', 'Was ist kein guter Einsatz einer kleinen, lustigen Herausforderung?', '["Ihre Kaffeebestellung erraten", "Sie zwei Optionen bewerten und sich entscheiden lassen", "Sie zu etwas abfragen, das sie nicht weiß", "Aus einer Frage ein verspieltes Ratespiel machen"]'::jsonb, 'Eine Herausforderung sollte ihr nie das Gefühl geben, nicht zu genügen. Es soll Spaß machen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cde2d207-7899-48ff-a104-fbf28135a2b2', 'de', 'Woran erkennst du, dass ihr mehr Nähe angenehm ist?', '["Sie bleibt im Gespräch, wenn du näher kommst", "Sie lehnt sich vor oder rückt zu dir", "Sie hält das ganze Gespräch über Blickkontakt"]'::jsonb, 'Wohlgefühl zeigt sich durch Ruhe, Erwidern und entspannte Beteiligung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ce4b3a53-6296-4e5e-9208-4ef8f7666fd8', 'de', 'Welche Einstellung hilft dir, Blickkontakt gut einzusetzen?', '["„Ich muss sie beeindrucken.“", "„Ich sollte Peinlichkeit vermeiden.“", "„Ich fühl mich wohl damit, gesehen zu werden.“", "„Ich muss etwas Kluges sagen.“"]'::jsonb, 'Blickkontakt, der Spannung erzeugt, kommt daher, dass du dich mit deiner Präsenz wohlfühlst, nicht vom Schauspielern.')
