insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cebe76a8-b37d-42fc-a5ff-e7a9ecc85c3c', 'de', 'Du fängst in einer Bar an, mit einer Frau zu flirten. Was sollte dein Hauptziel sein?', '["Ihre Nummer bekommen oder sie heute Abend mit nach Hause nehmen", "Jetzt einen lustigen, schönen Moment schaffen", "Sie mit Komplimenten und Spannung beeindrucken", "Beweisen, dass du selbstbewusst bist und es wert bist"]'::jsonb, 'Ein Flirt ist gelungen, wenn sich der Moment leichter und lebendiger anfühlt, egal was dabei herauskommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1e81b89-292c-47d2-881c-2ead24b571e1', 'de', 'Warum funktionieren Komplimente zu Mühe oder Ausdruck besser als Komplimente zum Aussehen?', '["Sie wirken intellektueller", "Sie machen weniger Druck und wirken persönlicher", "Sie lassen dich interessanter wirken", "Sie sind schwerer zu machen"]'::jsonb, 'Komplimente, die Entscheidungen und Mühe würdigen, fühlen sich sicherer an und verbinden mehr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5e4ef95-c1aa-4bd2-a5ca-49fc6afba2c8', 'de', 'Welches Verhalten kann dazu führen, dass sich Menschen zurückziehen?', '["Neutrale Körpersprache", "Einfache Fragen stellen", "Kurze Gespräche", "Wenig oder schwere Energie mitbringen"]'::jsonb, 'Menschen entfernen sich instinktiv von Stimmungen, die Kraft rauben.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d057ce-7c4d-495e-b2d7-fcc87a1c4105', 'de', 'Sie sagt: „Ich bin bei Männern sehr wählerisch.“ Mit welchem Satz könntest du sie disqualifizieren?', '["„Gut so, das solltest du auch sein.“", "„Was ist dein Typ?“", "„Ich versuch, deinen Ansprüchen gerecht zu werden.“", "„Perfekt, ich bin nämlich auch wählerisch.“"]'::jsonb, 'Die verspielte Umkehr zeigt eigene Ansprüche und Augenhöhe, ohne um Zustimmung zu werben.')
