insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e7cbc051-5503-4e4c-b6fd-0a4dea2be140', 'de', 'Sie erzählt von einer kreativen Lösung für ein Problem. Welches Kompliment kommt am besten an?', '["„Du bist umwerfend.“", "„Echt clever gelöst. Da wär ich nicht drauf gekommen.“", "„Du bist so intelligent.“", "„Deine Stimme ist beruhigend.“"]'::jsonb, 'Es geht um ihre kreative Entscheidung, und sie fühlt sich für ihr Denken gesehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e91466f0-24f3-4932-ab70-eab86651982c', 'de', 'Welche Stellen sind für eine frühe, fein abgestimmte Berührung in der Regel unbedenklich?', '["Unterarm", "Schulter", "Oberarm", "Taille oder Hüfte"]'::jsonb, 'Frühe Berührung sollte nicht intim sein und zur Situation passen.')
