insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea410aea-176d-48e3-8281-7a8a1353ca46', 'de', 'Die Stimmung ist super, aber es gab noch keine Berührung. Sie berührt leicht deinen Arm. Was könntest du tun?', '["Es ignorieren und Abstand halten", "Ihre Berührung kommentieren", "Sie sofort mehr berühren", "Später in einem natürlichen Moment mit einer leichten Berührung erwidern"]'::jsonb, 'Erwidere ihr Signal nach und nach, damit es für euch beide angenehm bleibt.')
