insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ebdbe221-f51b-4b0c-bd4b-aae266f0bcb8', 'de', 'Warum steigern Rückbezüge die Anziehung?', '["Sie zeigen Dominanz", "Sie zeigen Intelligenz", "Sie machen das Gespräch weniger anstrengend", "Sie zeigen Aufmerksamkeit und Vertrautheit"]'::jsonb, 'Wer sich erinnert fühlt, fühlt sich gesehen, und das vertieft Vertrautheit und Verbindung.')
