insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec7b6208-0886-41d6-bcde-5876126e4cad', 'de', 'Was lässt Blickkontakt anziehend statt unangenehm wirken?', '["Wärme", "Eine entspannte Haltung", "Ein ruhiges Tempo", "Ihn verbissen halten"]'::jsonb, 'Spannung entsteht aus Leichtigkeit und Präsenz, nicht aus Druck.')
