insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efb89d58-f624-4e43-8edf-0cee0dad7d5c', 'de', 'Was zeichnet gute Energie aus?', '["Warm", "Geerdet", "Leicht fröhlich", "Intensiv und dominant"]'::jsonb, 'Gute Energie wirkt einladend und sicher, nicht überwältigend oder kraftraubend.')
