insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f23233f3-ec06-4834-bf59-d052a683bed7', 'de', 'Welches Verhalten kann ohne Worte knisternde Spannung erzeugen?', '["Den Blickkontakt einen Moment länger halten", "Etwas näher stehen, wenn die Verbindung wärmer wird", "Fragen im Schnellfeuer, um den Schwung zu halten", "Eine Berührung kurz andauern lassen, wenn sie es erwidert"]'::jsonb, 'Nonverbale Signale, die die reine Freundlichkeit leicht durchbrechen, deuten eine Möglichkeit an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f442e1ff-0765-4613-91d3-e838e3234d98', 'de', 'Was ist gute Energie beim Flirten?', '["Ein warmer, geerdeter Ton", "Fröhlich, ohne zu überwältigen", "Flach und neutral, um keine Fehler zu machen", "Etwas über der Stimmung des Moments"]'::jsonb, 'Gute Energie hebt die Stimmung und lässt andere sich lebendig fühlen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5266e4f-abf4-4ecb-b84d-f1a01c78df7c', 'de', 'Was macht aus einem „netten“ Kompliment am zuverlässigsten eines voller Begehren?', '["Intensivere Worte", "Mehr Details zu ihrem Outfit", "Ton, Blickkontakt und Tempo", "Es lauter sagen"]'::jsonb, 'Dieselben Worte können freundlich oder aufgeladen wirken, je nachdem, wie du sie sagst.')
