insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6cb6b9f-3832-422f-a15d-ba9827f8dbf8', 'de', 'Du kommst näher, und sie tritt ein wenig zurück. Was solltest du tun?', '["Wieder näher kommen, um Selbstbewusstsein zu zeigen", "Das Gespräch beenden", "Fragen, ob ihr das unangenehm ist", "Ihr mehr Raum lassen und ruhig weitermachen"]'::jsonb, 'Respektier ihr Signal und geh wieder auf Abstand, damit Wohlgefühl und Vertrauen bleiben.')
