insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6feba7a-6f51-4a47-b8a8-d65c8f9ea942', 'de', 'Du führst sie durch eine volle Menge. Welche Berührung passt?', '["Keine Berührung nötig", "Den Arm um ihre Schultern legen", "Eine leichte Berührung am Arm, um ihr den Weg zu zeigen"]'::jsonb, 'Eine kurze, zweckmäßige Orientierung passt zur Situation und schafft Wohlgefühl.')
