insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f798a3d2-77df-4e98-b5f6-850a383b86e9', 'de', 'Warum baut dezentes Spiegeln so wirksam eine Verbindung auf?', '["Es signalisiert unbewusst Sicherheit und dass ihr zusammenpasst", "Sie hat das Gefühl, dass du vertraut und vertrauenswürdig bist", "Es zeigt ohne Worte Ähnlichkeit", "Alle oben genannten"]'::jsonb, 'Spiegeln signalisiert unbewusst Vertrautheit und Leichtigkeit, und das stärkt die Verbindung.')
