insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7b1d87a-9566-45e6-a098-77d7a9c2ebaf', 'de', 'Sie setzt sich, und du stehst über ihr. Was könntest du tun, um sie besser zu spiegeln?', '["Fragen, ob du dich auch setzen kannst, damit ihr auf einer Höhe seid", "Stehen bleiben, um eine selbstbewusste Haltung zu wahren", "Dich leicht vorbeugen, um auf ihre Augenhöhe zu kommen"]'::jsonb, 'Auf derselben Höhe zu sein verringert das Ungleichgewicht und schafft unbewusst Wohlgefühl.')
