insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7dc51a9-b997-4ed3-a54b-5996a6886069', 'de', 'Warum fühlen sich Menschen ganz natürlich zu aufbauender Energie hingezogen?', '["Warmherzige Menschen sind von Natur aus attraktiver und charismatischer", "Menschen schützen ihre Stimmung: Sie suchen, was sie hebt, und meiden, was sie runterzieht", "Mitreißende Energie signalisiert Selbstbewusstsein und sozialen Status"]'::jsonb, 'Menschen bewegen sich auf das zu, was sich gut anfühlt, und weg von dem, was es nicht tut.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fabb2d4d-834e-4aed-9716-9cafe7b3c118', 'de', 'Sie stand gerade und lehnt sich jetzt an die Bar. Beste Reaktion?', '["Gerade stehen bleiben: Zu offensichtliches Spiegeln ist peinlich", "Fragen, ob sie müde ist, weil sie sich jetzt anlehnt", "Dich ganz natürlich auch anlehnen und so ihre grobe Haltungsänderung spiegeln"]'::jsonb, 'Dezentes Angleichen schafft Wohlgefühl, ohne gespielt zu wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fbd08cf5-bc99-4004-98d5-438bd2be4a9c', 'de', 'Welche Formen des Spiegelns wirken?', '["Ihre Haltung oder ihren Stand aufgreifen", "Jede kleine Bewegung sofort nachmachen", "Energie und Tempo angleichen", "Die Lautstärke an ihre anpassen"]'::jsonb, 'Spiegeln signalisiert unbewusst Vertrautheit und Leichtigkeit, und das stärkt die Verbindung.')
